	used := int64(2960)
	if end := int64(b.Projection.Samples.OffsetOf) + int64(b.Projection.Samples.Count)*int64(b.Projection.Samples.Stride); end > used {
		used = end
	}
	if end := int64(b.Projection.Live.OffsetOf) + int64(b.Projection.Live.Count)*int64(b.Projection.Live.Stride); end > used {
		used = end
	}
	if end := int64(b.Projection.LiveSeen.OffsetOf) + int64(b.Projection.LiveSeen.Count)*int64(b.Projection.LiveSeen.Stride); end > used {
		used = end
	}
